function run(input){
  var f=input.formula;
  if(f==='ohm_v') return {result: input.i*input.r, unit:'volt'};
  if(f==='ohm_i') { if(input.r===0) throw new Error('R zero nahi'); return {result: input.v/input.r, unit:'ampere'}; }
  if(f==='ohm_r') { if(input.i===0) throw new Error('I zero nahi'); return {result: input.v/input.i, unit:'ohm'}; }
  if(f==='proj_range'){ var g=9.81; return {result: (input.v*input.v*Math.sin(2*input.theta*Math.PI/180))/g, unit:'meter'}; }
  if(f==='proj_height'){ var g2=9.81; return {result: (input.v*input.v*Math.sin(input.theta*Math.PI/180)*Math.sin(input.theta*Math.PI/180))/(2*g2), unit:'meter'}; }
  if(f==='kin_v') return {result: input.u + input.a*input.t, unit:'m/s'};
  if(f==='kin_s') return {result: input.u*input.t + 0.5*input.a*input.t*input.t, unit:'meter'};
  if(f==='unit_len'){ var m={'mm':0.001,'cm':0.01,'m':1,'km':1000,'in':0.0254,'ft':0.3048,'mi':1609.34};
    if(!(input.from in m)||!(input.to in m)) throw new Error('Unit: mm cm m km in ft mi');
    return {result: input.val*m[input.from]/m[input.to], unit:input.to}; }
  if(f==='unit_temp'){ var t=input.val;
    if(input.from==='C'&&input.to==='F') return {result: t*9/5+32, unit:'F'};
    if(input.from==='F'&&input.to==='C') return {result: (t-32)*5/9, unit:'C'};
    if(input.from==='C'&&input.to==='K') return {result: t+273.15, unit:'K'};
    if(input.from==='K'&&input.to==='C') return {result: t-273.15, unit:'C'};
    throw new Error('Temp: C F K me convert karo'); }
  throw new Error('Galat formula: '+f);
}
